Appends `text` as one field, quoted when it holds `separator`, a quote or a line break.

```
let mut line = String::new();
ravenrs_core::csv::push_field(&mut line, "Smith, \"J\"", ',');
assert_eq!(line, "\"Smith, \"\"J\"\"\"");
```
